/* ============================== WHATSAPP HELPERS ============================== */
/* Ponto único para gerar links wa.me funcionais em todo o site (produto, carrinho, checkout, botão flutuante). */
function buildWhatsAppUrl(message) {
  const digits = String(SITE.whatsapp || '').replace(/\D/g, '');
  return `https://wa.me/${digits}${message ? `?text=${encodeURIComponent(message)}` : ''}`;
}
function openWhatsApp(message) {
  if (typeof window === 'undefined') return;
  window.open(buildWhatsAppUrl(message), '_blank', 'noopener,noreferrer');
}
function buildProductWhatsAppMessage(product, qty) {
  return `Olá ${SITE.name}! Tenho interesse neste produto:\n\nProduto: ${product.name}\nQuantidade: ${qty}\nPreço: ${formatMT(product.price)}\n\nGostaria de saber mais informações.`;
}
function buildCartWhatsAppMessage(cart, cartTotal, form) {
  const lines = [];
  lines.push(`Olá ${SITE.name}! Quero fazer uma encomenda.`, '', 'Produtos:');
  cart.forEach((item, idx) => {
    const product = getProduct(item.productId);
    if (!product) return;
    lines.push(`${idx + 1}. ${product.name}`, `Quantidade: ${item.qty}`, `Preço: ${formatMT(product.price)}`, '');
  });
  lines.push(`Total: ${formatMT(cartTotal)}`);
  if (form) {
    lines.push('', 'Dados do cliente:', `Nome: ${form.fullName}`, `Telefone: ${form.phone}`, `Cidade: ${form.city}`, `Bairro: ${form.neighborhood}`, `Endereço: ${form.address}`);
    if (form.reference) lines.push(`Referência: ${form.reference}`);
    if (form.notes) lines.push(`Observação: ${form.notes}`);
  }
  lines.push('', 'Obrigado.');
  return lines.join('\n');
}

