/* ============================== VALIDATION HELPERS ============================== */
/* Centralizadas para reforçar segurança/consistência dos dados introduzidos pelo cliente. */

/* Valida números de telemóvel de Moçambique: aceita +258/258 opcional seguido de 9 dígitos
   começados por 8 (ex: 84, 85, 86, 87, 82, 83), com ou sem espaços. */

/* NOTA: Email NÃO é obrigatório para o cliente (ver secção 29 da especificação).
   O checkout funciona apenas com Nome, Telefone, Cidade, Bairro e Endereço. */
function validateCheckoutForm(form) {
  const errors = {};
  if (!form.fullName.trim() || form.fullName.trim().length < 3) errors.fullName = 'Indique o nome completo';
  if (!PHONE_MZ_RE.test(form.phone.trim())) errors.phone = 'Indique um número de telemóvel válido de Moçambique (ex: 84 123 4567)';
  if (!form.city.trim()) errors.city = 'Campo obrigatório';
  if (!form.neighborhood.trim()) errors.neighborhood = 'Campo obrigatório';
  if (!form.address.trim() || form.address.trim().length < 5) errors.address = 'Indique um endereço válido';
  return errors;
}
function useDebouncedValue(value, delay = 250) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}
/* Persistência localStorage — carrinho e favoritos sobrevivem a recarregamento da página. */
function useLocalStorage(key, initialValue) {
  const [storedValue, setStoredValue] = useState(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch {
      return initialValue;
    }
  });
  const setValue = (value) => {
    try {
      const valueToStore = typeof value === 'function' ? value(storedValue) : value;
      setStoredValue(valueToStore);
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
    } catch {
      setStoredValue(typeof value === 'function' ? value(storedValue) : value);
    }
  };
  return [storedValue, setValue];
}

