/* ============================== PRODUCT CARD ============================== */
/* memo() evita re-renderizações desnecessárias em grelhas grandes (eficiência). */
function ProductVisual({ product, className = 'w-full h-full object-contain', fallbackClassName = 'w-32 h-36 md:w-36 md:h-40', loading = 'lazy', uidPrefix = 'product' }) {
  const [failed, setFailed] = useState(false);
  const photo = getProductPhoto(product.photo);

  if (photo && !failed) {
    return (
      <img
        src={photo}
        alt={product.name}
        className={className}
        loading={loading}
        onError={() => setFailed(true)}
      />
    );
  }

  return (
    <ProductArt
      variant={product.variant}
      tone={product.tone}
      uid={`${uidPrefix}-${product.id}`}
      className={fallbackClassName}
    />
  );
}

const ProductCard = memo(function ProductCard({ product, onAdd, onToggleFav, isFav, onOpen }) {
  return (
    <div className="product-card card overflow-hidden flex flex-col">
      <button onClick={() => onOpen(product.id)} className="relative bg-cream-soft aspect-square flex items-center justify-center p-6 overflow-hidden" style={{ background: 'var(--bg-soft)' }}>
        {product.tag && (
          <span
            className="absolute top-3 left-3 text-[11px] font-medium px-2.5 py-1 rounded-full text-white"
            style={{ background: product.tag === 'Promoção' ? 'var(--rose)' : 'var(--primary)' }}
          >
            {product.tag}
          </span>
        )}
        <ProductVisual product={product} uidPrefix="card" />
      </button>
      <div className="p-4 flex flex-col flex-1">
        <span className="text-xs uppercase tracking-wide text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
          {CATEGORIES.find((c) => c.id === product.category)?.name}
        </span>
        <button onClick={() => onOpen(product.id)} className="text-left font-display text-base mt-1 mb-1 leading-snug">
          {product.name}
        </button>
        <div className="flex items-center gap-1.5 mb-2">
          <Stars rating={product.rating} size={13} />
          <span className="text-xs text-ink-soft" style={{ color: 'var(--ink-soft)' }}>({product.reviews})</span>
        </div>
        <div className="mt-auto flex items-center justify-between pt-2">
          <div>
            {product.oldPrice && (
              <div className="text-xs text-ink-soft line-through" style={{ color: 'var(--ink-soft)' }}>{formatMT(product.oldPrice)}</div>
            )}
            <div className="font-medium" style={{ color: product.oldPrice ? 'var(--rose)' : 'var(--ink)' }}>{formatMT(product.price)}</div>
          </div>
          <div className="flex items-center gap-2">
            <button aria-label="Adicionar aos favoritos" onClick={() => onToggleFav(product.id)} className={`heart-btn ${isFav ? 'active' : ''}`}>
              <Heart size={16} />
            </button>
            <button
              aria-label="Adicionar ao carrinho"
              onClick={() => onAdd(product.id)}
              disabled={!product.stock}
              className="heart-btn"
              style={{ background: product.stock ? 'var(--primary)' : '#eee', color: product.stock ? '#fff' : '#999', borderColor: product.stock ? 'var(--primary)' : 'var(--line)' }}
            >
              <ShoppingBag size={16} />
            </button>
          </div>
        </div>
        {!product.stock && <div className="text-xs mt-2" style={{ color: 'var(--rose)' }}>Esgotado</div>}
      </div>
    </div>
  );
});

