/* ============================== PRODUCTS PAGE ============================== */
function ProductsPage({ goTo, onAdd, onToggleFav, favorites, onOpen, initialCategory, initialSegment, initialSearch }) {
  const [search, setSearch] = useState(initialSearch || '');
  const [segment, setSegment] = useState(initialSegment || 'all');
  const [category, setCategory] = useState(initialCategory || 'all');
  const [priceRange, setPriceRange] = useState('all');
  const [sortBy, setSortBy] = useState('relevance');

  useEffect(() => { setCategory(initialCategory || 'all'); }, [initialCategory]);
  useEffect(() => { setSegment(initialSegment || 'all'); }, [initialSegment]);
  useEffect(() => { setSearch(initialSearch || ''); }, [initialSearch]);

  const debouncedSearch = useDebouncedValue(search, 200);

  const visibleCategories = useMemo(
    () => (segment === 'all' ? CATEGORIES : CATEGORIES.filter((c) => c.segment === segment)),
    [segment]
  );

  const filtered = useMemo(() => {
    let list = PRODUCTS.filter((p) => {
      const matchesSegment = segment === 'all' || p.segment === segment;
      const matchesCategory = category === 'all' || p.category === category;
      const matchesSearch = p.name.toLowerCase().includes(debouncedSearch.toLowerCase());
      const matchesPrice =
        priceRange === 'all' ||
        (priceRange === 'low' && p.price < 700) ||
        (priceRange === 'mid' && p.price >= 700 && p.price <= 1200) ||
        (priceRange === 'high' && p.price > 1200);
      return matchesSegment && matchesCategory && matchesSearch && matchesPrice;
    });
    if (sortBy === 'price-asc') list = [...list].sort((a, b) => a.price - b.price);
    if (sortBy === 'price-desc') list = [...list].sort((a, b) => b.price - a.price);
    if (sortBy === 'popular') list = [...list].sort((a, b) => b.reviews - a.reviews);
    return list;
  }, [segment, category, debouncedSearch, priceRange, sortBy]);

  return (
    <div className="max-w-7xl mx-auto px-5 md:px-8 py-10">
      <div className="mb-8">
        <span className="text-xs uppercase tracking-widest" style={{ color: 'var(--accent)' }}>Catálogo</span>
        <h1 className="font-display text-3xl md:text-4xl mt-1">Todos os produtos</h1>
      </div>

      <div className="flex items-center gap-2 bg-white border rounded-full px-4 py-2.5 mb-6 max-w-md" style={{ borderColor: 'var(--line)' }}>
        <Search size={16} className="text-ink-soft" style={{ color: 'var(--ink-soft)' }} />
        <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Pesquisar produtos..." className="flex-1 outline-none bg-transparent text-sm" />
      </div>

      <div className="flex flex-wrap gap-2 mb-3">
        <button onClick={() => { setSegment('all'); setCategory('all'); }} className={`chip ${segment === 'all' ? 'active' : ''}`}>Todos os segmentos</button>
        {SEGMENTS.map((s) => (
          <button key={s.id} onClick={() => { setSegment(s.id); setCategory('all'); }} className={`chip ${segment === s.id ? 'active' : ''}`}>{s.name}</button>
        ))}
      </div>

      <div className="flex flex-wrap gap-2 mb-4">
        <button onClick={() => setCategory('all')} className={`chip ${category === 'all' ? 'active' : ''}`}>Todas as categorias</button>
        {visibleCategories.map((c) => (
          <button key={c.id} onClick={() => setCategory(c.id)} className={`chip ${category === c.id ? 'active' : ''}`}>{c.name}</button>
        ))}
      </div>

      {segment === 'saude' && (
        <p className="text-xs text-ink-soft mb-4 max-w-2xl" style={{ color: 'var(--ink-soft)' }}>
          Os suplementos não substituem uma dieta variada e equilibrada nem um estilo de vida saudável. Consulte um profissional de saúde antes de iniciar qualquer suplementação.
        </p>
      )}

      <div className="flex flex-wrap items-center gap-3 mb-8 pb-6 border-b" style={{ borderColor: 'var(--line)' }}>
        <div className="flex items-center gap-2">
          <label className="text-xs text-ink-soft" style={{ color: 'var(--ink-soft)' }}>Preço</label>
          <select value={priceRange} onChange={(e) => setPriceRange(e.target.value)} className="input-field py-2 text-sm w-auto">
            <option value="all">Todos os preços</option>
            <option value="low">Até 700 MT</option>
            <option value="mid">700 MT – 1.200 MT</option>
            <option value="high">Acima de 1.200 MT</option>
          </select>
        </div>
        <div className="flex items-center gap-2">
          <label className="text-xs text-ink-soft" style={{ color: 'var(--ink-soft)' }}>Ordenar</label>
          <select value={sortBy} onChange={(e) => setSortBy(e.target.value)} className="input-field py-2 text-sm w-auto">
            <option value="relevance">Relevância</option>
            <option value="price-asc">Menor preço</option>
            <option value="price-desc">Maior preço</option>
            <option value="popular">Mais populares</option>
          </select>
        </div>
        <span className="text-xs text-ink-soft ml-auto" style={{ color: 'var(--ink-soft)' }}>{filtered.length} produto(s)</span>
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-20 text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
          Nenhum produto encontrado. Tente ajustar a pesquisa ou os filtros.
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
          {filtered.map((p) => (
            <ProductCard key={p.id} product={p} onAdd={onAdd} onToggleFav={onToggleFav} isFav={favorites.includes(p.id)} onOpen={onOpen} />
          ))}
        </div>
      )}
    </div>
  );
}

/* ============================== PRODUCT DETAIL PAGE ============================== */
function ProductDetailPage({ productId, goTo, onAdd, onToggleFav, favorites, onOpen }) {
  const product = getProduct(productId);
  const [qty, setQty] = useState(1);
  const [activeImg, setActiveImg] = useState(0);

  if (!product) return <div className="max-w-7xl mx-auto px-5 py-20 text-center">Produto não encontrado.</div>;

  const related = PRODUCTS.filter((p) => p.category === product.category && p.id !== product.id).slice(0, 4);
  const isFav = favorites.includes(product.id);
  const gallery = [product.tone, 'ink', 'ochre'];

  return (
    <div className="max-w-7xl mx-auto px-5 md:px-8 py-10">
      <button onClick={() => goTo('products')} className="flex items-center gap-1 text-sm text-ink-soft mb-8" style={{ color: 'var(--ink-soft)' }}>
        <ChevronLeft size={16} /> Voltar aos produtos
      </button>

      <div className="grid md:grid-cols-2 gap-10 md:gap-16 mb-16">
        <div>
          <div className="card aspect-square flex items-center justify-center p-10 mb-4 overflow-hidden" style={{ background: 'var(--bg-soft)' }}>
            {getProductPhoto(product.photo) ? (
              <ProductVisual product={product} className="w-full h-full object-contain" loading="eager" uidPrefix="detail" />
            ) : (
              <ProductArt variant={product.variant} tone={gallery[activeImg]} uid={`detail-${product.id}-${activeImg}`} className="w-52 h-56" />
            )}
          </div>
          {getProductPhoto(product.photo) ? (
            <p className="text-xs text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
              {product.photo === 'lineOneGroup' ? 'Foto ilustrativa fornecida pelo fornecedor (produto em conjunto com outros da mesma marca).' : 'Foto fornecida pelo fornecedor.'}
            </p>
          ) : (
            <div className="flex gap-3">
              {gallery.map((tone, i) => (
                <button
                  key={i}
                  onClick={() => setActiveImg(i)}
                  className="card p-3 w-20 h-20 flex items-center justify-center"
                  style={{ background: 'var(--bg-soft)', borderColor: activeImg === i ? 'var(--primary)' : 'var(--line)', borderWidth: activeImg === i ? 2 : 1 }}
                >
                  <ProductArt variant={product.variant} tone={tone} uid={`thumb-${product.id}-${i}`} className="w-10 h-11" />
                </button>
              ))}
            </div>
          )}
        </div>

        <div>
          <span className="text-xs uppercase tracking-wide text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
            {CATEGORIES.find((c) => c.id === product.category)?.name}
          </span>
          <h1 className="font-display text-3xl md:text-4xl mt-1 mb-3">{product.name}</h1>
          <div className="flex items-center gap-2 mb-4">
            <Stars rating={product.rating} size={16} />
            <span className="text-sm text-ink-soft" style={{ color: 'var(--ink-soft)' }}>{product.rating} · {product.reviews} avaliações</span>
          </div>

          <div className="flex items-baseline gap-3 mb-5">
            {product.oldPrice && <span className="text-ink-soft line-through" style={{ color: 'var(--ink-soft)' }}>{formatMT(product.oldPrice)}</span>}
            <span className="font-display text-3xl" style={{ color: product.oldPrice ? 'var(--rose)' : 'var(--ink)' }}>{formatMT(product.price)}</span>
          </div>

          <p className="text-ink-soft leading-relaxed mb-6" style={{ color: 'var(--ink-soft)' }}>{product.desc}</p>

          {product.type === 'suplemento' ? (
            <>
              <div className="mb-6 grid grid-cols-2 gap-3">
                <div className="card p-3">
                  <div className="text-xs text-ink-soft" style={{ color: 'var(--ink-soft)' }}>Porção</div>
                  <div className="text-sm font-medium">{product.servingSize}</div>
                </div>
                <div className="card p-3">
                  <div className="text-xs text-ink-soft" style={{ color: 'var(--ink-soft)' }}>Porções por embalagem</div>
                  <div className="text-sm font-medium">{product.servingsPerContainer}</div>
                </div>
              </div>

              <div className="mb-6">
                <div className="font-medium text-sm mb-2">Informação nutricional (por porção)</div>
                <div className="card overflow-hidden">
                  {product.nutritionFacts.map((n, i) => (
                    <div key={n.name} className="flex items-center justify-between px-4 py-2 text-sm" style={{ borderTop: i === 0 ? 'none' : '1px solid var(--line)' }}>
                      <span className="text-ink-soft" style={{ color: 'var(--ink-soft)' }}>{n.name}</span>
                      <span className="font-medium">{n.amount}{n.dv && n.dv !== '—' ? ` · ${n.dv} VD*` : ''}</span>
                    </div>
                  ))}
                </div>
                <p className="text-[11px] text-ink-soft mt-1.5" style={{ color: 'var(--ink-soft)' }}>*VD: Valor Diário de referência.</p>
              </div>

              <div className="mb-6">
                <div className="font-medium text-sm mb-1.5">Ingredientes</div>
                <p className="text-sm text-ink-soft leading-relaxed" style={{ color: 'var(--ink-soft)' }}>{product.ingredients}</p>
              </div>

              <div className="mb-6">
                <div className="font-medium text-sm mb-1.5">Modo de utilização</div>
                <p className="text-sm text-ink-soft leading-relaxed" style={{ color: 'var(--ink-soft)' }}>{product.usage}</p>
              </div>

              <div className="mb-6 card p-4" style={{ borderColor: 'var(--rose)', background: 'var(--accent-soft)' }}>
                <div className="flex items-center gap-2 font-medium text-sm mb-2">
                  <AlertCircle size={16} style={{ color: 'var(--rose)' }} /> Informações importantes
                </div>
                <div className="space-y-2 text-sm text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
                  <p><span className="font-medium text-ink">Alérgenos: </span>{product.allergens}</p>
                  <p><span className="font-medium text-ink">Advertências: </span>{product.warnings}</p>
                  <p><span className="font-medium text-ink">Conservação: </span>{product.storage}</p>
                </div>
              </div>
            </>
          ) : (
            <>
              <div className="mb-6">
                <div className="font-medium text-sm mb-2">Benefícios</div>
                <ul className="space-y-1.5">
                  {product.benefits.map((b) => (
                    <li key={b} className="flex items-start gap-2 text-sm text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
                      <Check size={15} className="mt-0.5 flex-shrink-0" style={{ color: 'var(--primary)' }} /> {b}
                    </li>
                  ))}
                </ul>
              </div>

              <div className="mb-6">
                <div className="font-medium text-sm mb-1.5">Ingredientes</div>
                <p className="text-sm text-ink-soft leading-relaxed" style={{ color: 'var(--ink-soft)' }}>{product.ingredients}</p>
              </div>
            </>
          )}

          <div className="flex items-center gap-2 mb-6">
            <span className="w-2 h-2 rounded-full" style={{ background: product.stock ? 'var(--primary)' : 'var(--rose)' }} />
            <span className="text-sm font-medium">{product.stock ? 'Disponível em stock' : 'Esgotado'}</span>
          </div>

          <div className="flex items-center gap-4 mb-6">
            <div className="flex items-center border rounded-full" style={{ borderColor: 'var(--line)' }}>
              <button onClick={() => setQty((q) => Math.max(1, q - 1))} className="p-3" aria-label="Diminuir quantidade"><Minus size={14} /></button>
              <span className="w-8 text-center text-sm font-medium">{qty}</span>
              <button onClick={() => setQty((q) => Math.min(99, q + 1))} className="p-3" aria-label="Aumentar quantidade"><Plus size={14} /></button>
            </div>
            <button aria-label="Adicionar aos favoritos" onClick={() => onToggleFav(product.id)} className={`heart-btn ${isFav ? 'active' : ''}`} style={{ width: '2.75rem', height: '2.75rem' }}>
              <Heart size={18} />
            </button>
          </div>

          <div className="flex flex-col sm:flex-row gap-3">
            <button disabled={!product.stock} onClick={() => onAdd(product.id, qty)} className="btn-secondary justify-center flex-1">
              <ShoppingBag size={16} /> Adicionar ao carrinho
            </button>
            <button
              disabled={!product.stock}
              onClick={() => { onAdd(product.id, qty); goTo('checkout'); }}
              className="btn-primary justify-center flex-1"
            >
              Comprar agora
            </button>
          </div>
          <button
            disabled={!product.stock}
            onClick={() => openWhatsApp(buildProductWhatsAppMessage(product, qty))}
            aria-label={`Encomendar ${product.name} pelo WhatsApp`}
            className="justify-center flex w-full items-center gap-2 mt-3 rounded-full py-3 text-sm font-medium text-white disabled:opacity-50"
            style={{ background: '#25D366' }}
          >
            <Phone size={16} /> Encomendar pelo WhatsApp
          </button>
        </div>
      </div>

      <div className="mb-16">
        <h2 className="font-display text-2xl mb-5">Avaliações</h2>
        <div className="grid md:grid-cols-3 gap-5">
          {REVIEWS.slice(0, 3).map((r) => (
            <div key={r.name} className="card p-5">
              <div className="flex items-center gap-3 mb-2">
                <Avatar initials={r.initials} tone={r.tone} size={38} />
                <div>
                  <div className="font-medium text-sm">{r.name}</div>
                  <Stars rating={r.rating} size={12} />
                </div>
              </div>
              <p className="text-sm text-ink-soft leading-relaxed" style={{ color: 'var(--ink-soft)' }}>&ldquo;{r.comment}&rdquo;</p>
            </div>
          ))}
        </div>
      </div>

      {related.length > 0 && (
        <div>
          <h2 className="font-display text-2xl mb-5">Produtos relacionados</h2>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6">
            {related.map((p) => (
              <ProductCard key={p.id} product={p} onAdd={onAdd} onToggleFav={onToggleFav} isFav={favorites.includes(p.id)} onOpen={onOpen} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================== CART PAGE ============================== */
function CartPage({ cart, goTo, updateQty, removeFromCart, cartTotal }) {
  return (
    <div className="max-w-5xl mx-auto px-5 md:px-8 py-10">
      <h1 className="font-display text-3xl md:text-4xl mb-8">O seu carrinho</h1>
      {cart.length === 0 ? (
        <div className="text-center py-20">
          <ShoppingBag size={40} className="mx-auto mb-4" style={{ color: 'var(--line)' }} />
          <p className="text-ink-soft mb-6" style={{ color: 'var(--ink-soft)' }}>O seu carrinho está vazio.</p>
          <button onClick={() => goTo('products')} className="btn-primary">Continuar comprando</button>
        </div>
      ) : (
        <div className="grid md:grid-cols-3 gap-10">
          <div className="md:col-span-2 flex flex-col gap-4">
            {cart.map((item) => {
              const product = getProduct(item.productId);
              if (!product) return null;
              return (
                <div key={item.productId} className="card p-4 flex items-center gap-4">
                  <button onClick={() => goTo('product-detail', { productId: product.id })} className="w-20 h-20 flex items-center justify-center rounded-xl flex-shrink-0 overflow-hidden" style={{ background: 'var(--bg-soft)' }}>
                    <ProductVisual product={product} className="w-full h-full object-contain" fallbackClassName="w-14 h-16" uidPrefix="cart" />
                  </button>
                  <div className="flex-1 min-w-0">
                    <button onClick={() => goTo('product-detail', { productId: product.id })} className="font-medium text-sm text-left block truncate">{product.name}</button>
                    <div className="text-sm text-ink-soft" style={{ color: 'var(--ink-soft)' }}>{formatMT(product.price)}</div>
                    <div className="flex items-center border rounded-full mt-2 w-fit" style={{ borderColor: 'var(--line)' }}>
                      <button onClick={() => updateQty(item.productId, item.qty - 1)} className="p-2" aria-label="Diminuir quantidade"><Minus size={12} /></button>
                      <span className="w-6 text-center text-xs font-medium">{item.qty}</span>
                      <button onClick={() => updateQty(item.productId, Math.min(99, item.qty + 1))} className="p-2" aria-label="Aumentar quantidade"><Plus size={12} /></button>
                    </div>
                  </div>
                  <div className="text-right flex flex-col items-end gap-2 flex-shrink-0">
                    <div className="font-medium text-sm">{formatMT(product.price * item.qty)}</div>
                    <button onClick={() => removeFromCart(item.productId)} aria-label="Remover produto" className="text-ink-soft hover:text-rose-500" style={{ color: 'var(--ink-soft)' }}>
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              );
            })}
            <button onClick={() => goTo('products')} className="text-sm font-medium text-primary flex items-center gap-1 mt-2" style={{ color: 'var(--primary)' }}>
              <ChevronLeft size={14} /> Continuar comprando
            </button>
          </div>

          <div className="card p-6 h-fit">
            <h2 className="font-display text-xl mb-4">Resumo</h2>
            <div className="flex justify-between text-sm mb-2">
              <span className="text-ink-soft" style={{ color: 'var(--ink-soft)' }}>Subtotal</span>
              <span>{formatMT(cartTotal)}</span>
            </div>
            <div className="flex justify-between text-sm mb-4">
              <span className="text-ink-soft" style={{ color: 'var(--ink-soft)' }}>Entrega</span>
              <span>{cartTotal >= SITE.freeShippingThreshold ? 'Grátis' : 'A calcular no checkout'}</span>
            </div>
            {cartTotal < SITE.freeShippingThreshold && (
              <div className="text-xs mb-4 px-3 py-2 rounded-lg" style={{ background: 'var(--accent-soft)', color: 'var(--accent)' }}>
                Faltam {formatMT(SITE.freeShippingThreshold - cartTotal)} para entrega grátis.
              </div>
            )}
            <div className="flex justify-between font-medium text-base border-t pt-4 mb-6" style={{ borderColor: 'var(--line)' }}>
              <span>Total</span>
              <span>{formatMT(cartTotal)}</span>
            </div>
            <button onClick={() => goTo('checkout')} className="btn-primary w-full justify-center">Finalizar compra</button>
            <button
              onClick={() => openWhatsApp(buildCartWhatsAppMessage(cart, cartTotal))}
              aria-label="Enviar pedido pelo WhatsApp"
              className="w-full justify-center flex items-center gap-2 rounded-full py-3 text-sm font-medium text-white mt-3"
              style={{ background: '#25D366' }}
            >
              <Phone size={16} /> Enviar pedido pelo WhatsApp
            </button>
            <div className="flex items-center justify-center gap-1.5 text-xs mt-4" style={{ color: 'var(--ink-soft)' }}>
              <Lock size={12} /> Os seus dados são usados apenas para esta encomenda
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================== CHECKOUT PAGE ============================== */
function CheckoutPage({ cart, cartTotal, goTo, onConfirmOrder }) {
  const [form, setForm] = useState({
    fullName: '', phone: '', city: '', neighborhood: '', address: '', reference: '', notes: '',
  });
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validateCheckoutForm(form);
    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) {
      // Se algum campo obrigatório estiver vazio/inválido: não abrir WhatsApp, mostrar o erro.
      const firstKey = Object.keys(newErrors)[0];
      const el = document.querySelector(`[name="${firstKey}"]`);
      if (el) el.focus();
      return;
    }
    setSubmitting(true);
    // Monta o resumo da encomenda, regista localmente e abre o WhatsApp com a mensagem pré-preenchida.
    // Não há processamento de pagamento nesta etapa — o pagamento é combinado diretamente com a AFA PrimeLife.
    setTimeout(() => {
      setSubmitting(false);
      const message = buildCartWhatsAppMessage(cart, cartTotal, form);
      openWhatsApp(message);
      onConfirmOrder(form);
    }, 500);
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-3xl mx-auto px-5 py-20 text-center">
        <p className="text-ink-soft mb-6" style={{ color: 'var(--ink-soft)' }}>O seu carrinho está vazio.</p>
        <button onClick={() => goTo('products')} className="btn-primary">Ver produtos</button>
      </div>
    );
  }

  const field = (label, key, type = 'text') => (
    <div>
      <label htmlFor={key} className="text-xs font-medium block mb-1.5">{label}</label>
      <input
        id={key}
        name={key}
        type={type}
        autoComplete="on"
        value={form[key]}
        onChange={(e) => set(key, e.target.value)}
        className="input-field"
        aria-invalid={!!errors[key]}
        aria-describedby={errors[key] ? `${key}-error` : undefined}
        style={errors[key] ? { borderColor: 'var(--rose)' } : {}}
      />
      {errors[key] && (
        <span id={`${key}-error`} className="text-xs flex items-center gap-1 mt-1" style={{ color: 'var(--rose)' }}>
          <AlertCircle size={12} /> {errors[key]}
        </span>
      )}
    </div>
  );

  return (
    <div className="max-w-6xl mx-auto px-5 md:px-8 py-10">
      <h1 className="font-display text-3xl md:text-4xl mb-8">Finalizar compra</h1>
      <div className="grid md:grid-cols-3 gap-10">
        <form onSubmit={handleSubmit} className="md:col-span-2 flex flex-col gap-5">
          <div className="grid sm:grid-cols-2 gap-5">
            {field('Nome completo', 'fullName')}
            {field('Telefone / WhatsApp', 'phone', 'tel')}
          </div>
          <div className="grid sm:grid-cols-2 gap-5">
            {field('Cidade', 'city')}
            {field('Bairro', 'neighborhood')}
          </div>
          {field('Endereço de entrega', 'address')}
          <div>
            <label htmlFor="reference" className="text-xs font-medium block mb-1.5">Referência do endereço (opcional)</label>
            <input id="reference" name="reference" type="text" value={form.reference} onChange={(e) => set('reference', e.target.value)} className="input-field" />
          </div>
          <div>
            <label className="text-xs font-medium block mb-1.5">Observações (opcional)</label>
            <textarea value={form.notes} onChange={(e) => set('notes', e.target.value)} className="input-field" rows={3} />
          </div>

          <div className="card p-4 flex items-start gap-3" style={{ borderColor: 'var(--primary)', borderWidth: 1 }}>
            <Phone size={18} className="mt-0.5 flex-shrink-0" style={{ color: 'var(--primary)' }} />
            <div className="text-sm">
              <div className="font-medium mb-1">Combinamos o pagamento consigo</div>
              <div className="text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
                Ao confirmar, vamos abrir o WhatsApp com o resumo da sua encomenda. Combinamos consigo a forma de pagamento e a entrega diretamente pelo número{' '}
                <strong>{SITE.whatsapp}</strong>. Não é feito nenhum pagamento online.
              </div>
            </div>
          </div>

          <div className="flex items-start gap-2 text-xs text-ink-soft" style={{ color: 'var(--ink-soft)' }}>
            <Lock size={13} className="mt-0.5 flex-shrink-0" />
            Os seus dados são usados apenas para processar esta encomenda. Não é necessário email.
          </div>

          <button type="submit" disabled={submitting} className="btn-primary justify-center mt-2" style={{ background: '#25D366', borderColor: '#25D366' }}>
            {submitting ? (<><Loader2 size={16} className="spin" /> A processar...</>) : (<><ShoppingBag size={16} /> Enviar encomenda pelo WhatsApp</>)}
          </button>
        </form>

        <div className="card p-6 h-fit">
          <h2 className="font-display text-xl mb-4">Resumo do pedido</h2>
          <div className="flex flex-col gap-3 mb-4">
            {cart.map((item) => {
              const product = getProduct(item.productId);
              if (!product) return null;
              return (
                <div key={item.productId} className="flex justify-between text-sm">
                  <span className="text-ink-soft" style={{ color: 'var(--ink-soft)' }}>{product.name} × {item.qty}</span>
                  <span>{formatMT(product.price * item.qty)}</span>
                </div>
              );
            })}
          </div>
          <div className="flex justify-between font-medium text-base border-t pt-4" style={{ borderColor: 'var(--line)' }}>
            <span>Total</span>
            <span>{formatMT(cartTotal)}</span>
          </div>
          <div className="flex items-center gap-1.5 text-xs mt-4 pt-4 border-t" style={{ color: 'var(--ink-soft)', borderColor: 'var(--line)' }}>
            <ShieldCheck size={13} /> Compra protegida · Pagamento combinado diretamente consigo
          </div>
        </div>
      </div>
    </div>
  );
}

