/* ============================== TOAST ============================== */
function Toast({ message }) {
  /* Suporta string legada ou { message, type } */
  const text = typeof message === 'string' ? message : message?.message;
  const type = typeof message === 'string' ? 'success' : (message?.type || 'success');
  if (!text) return null;
  const isError = type === 'error';
  return (
    <div className="fixed bottom-5 left-1/2 -translate-x-1/2 z-50 toast-anim" role="status" aria-live="polite">
      <div
        className="bg-white shadow-lg rounded-full px-5 py-3 flex items-center gap-2 text-sm font-medium border"
        style={{ borderColor: isError ? 'var(--rose)' : 'var(--line)' }}
      >
        {isError ? <AlertCircle size={15} style={{ color: 'var(--rose)' }} /> : <Check size={15} style={{ color: 'var(--primary)' }} />}
        {text}
      </div>
    </div>
  );
}

/* ============================== APP ============================== */
export default function App() {
  const [page, setPage] = useState('home');
  const [selectedProductId, setSelectedProductId] = useState(null);
  const [cart, setCart] = useLocalStorage('nala_cart', []);
  const [favorites, setFavorites] = useLocalStorage('nala_favorites', []);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchValue, setSearchValue] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');
  const [activeSegment, setActiveSegment] = useState('all');
  const [toast, setToast] = useState(null); /* { message, type: 'success'|'error' } ou string legada */
  const [orderNumber, setOrderNumber] = useState(null);
  const [scrollTarget, setScrollTarget] = useState(null);

  useEffect(() => {
    if (scrollTarget) {
      const el = document.getElementById(scrollTarget);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      setScrollTarget(null);
    }
  }, [page, scrollTarget]);

  useEffect(() => {
    if (toast) {
      const t = setTimeout(() => setToast(null), 2500);
      return () => clearTimeout(t);
    }
  }, [toast]);

  function goTo(nextPage, opts = {}) {
    setPage(nextPage);
    setMobileMenuOpen(false);
    setSearchOpen(false);
    if (opts.productId) setSelectedProductId(opts.productId);
    if (nextPage === 'products') {
      /* Se vier categoria explícita usa-a; senão repõe 'all' para evitar filtro fantasma */
      setActiveCategory(opts.category || 'all');
      setActiveSegment(opts.segment || 'all');
    }
    if (opts.scroll) {
      setScrollTarget(opts.scroll);
    } else {
      window.scrollTo({ top: 0, behavior: 'auto' });
    }
  }

  function onOpen(productId) {
    goTo('product-detail', { productId });
  }

  function onAdd(productId, qty = 1) {
    const product = getProduct(productId);
    if (!product || !product.stock) {
      setToast({ message: 'Produto esgotado — não foi possível adicionar ao carrinho', type: 'error' });
      return;
    }
    setCart((prev) => {
      const existing = prev.find((i) => i.productId === productId);
      if (existing) {
        return prev.map((i) => (i.productId === productId ? { ...i, qty: i.qty + qty } : i));
      }
      return [...prev, { productId, qty }];
    });
    setToast({ message: `${product.name} adicionado ao carrinho`, type: 'success' });
  }

  function updateQty(productId, qty) {
    if (qty < 1) {
      removeFromCart(productId);
      return;
    }
    setCart((prev) => prev.map((i) => (i.productId === productId ? { ...i, qty } : i)));
  }

  function removeFromCart(productId) {
    setCart((prev) => prev.filter((i) => i.productId !== productId));
  }

  function onToggleFav(productId) {
    setFavorites((prev) => (prev.includes(productId) ? prev.filter((id) => id !== productId) : [...prev, productId]));
  }

  function onSearchSubmit() {
    setActiveSearch(searchValue);
    setActiveCategory('all');
    goTo('products', { segment: 'all' });
  }

  function onConfirmOrder(form) {
    const num = `AFA-${Math.floor(100000 + Math.random() * 900000)}`;
    /* Estrutura preparada para integração futura com backend/API.
       Quando o backend existir: substituir o console.log por uma chamada fetch/axios. */
    const orderPayload = {
      orderNumber: num,
      status: 'PENDENTE',
      createdAt: new Date().toISOString(),
      customer: {
        fullName: form.fullName,
        phone: form.phone,
      },
      delivery: {
        city: form.city,
        neighborhood: form.neighborhood,
        address: form.address,
        reference: form.reference || '',
        notes: form.notes || '',
      },
      items: cart.map((item) => {
        const p = getProduct(item.productId);
        return {
          productId: item.productId,
          name: p?.name || '',
          price: p?.price || 0,
          qty: item.qty,
          subtotal: (p?.price || 0) * item.qty,
        };
      }),
      total: cartTotal,
      paymentStatus: 'AGUARDA_CONFIRMAÇÃO',
      paymentMethod: 'whatsapp',
    };
    /* TODO: await api.post('/orders', orderPayload); */
    console.info('[AFA PrimeLife] Encomenda criada (sem backend):', orderPayload);
    setOrderNumber(num);
    setCart([]);
    goTo('success');
  }

  const cartTotal = cart.reduce((sum, item) => {
    const product = getProduct(item.productId);
    return product ? sum + product.price * item.qty : sum;
  }, 0);
  const cartCount = cart.reduce((sum, item) => sum + item.qty, 0);

  const sharedProductProps = { onAdd, onToggleFav, favorites, onOpen };

  return (
    <div className="nala-root min-h-screen flex flex-col">
      <GlobalStyle />
      <a href="#conteudo-principal" className="skip-link">Saltar para o conteúdo</a>
      <TrustBar />
      <Header
        goTo={goTo}
        cartCount={cartCount}
        favCount={favorites.length}
        mobileMenuOpen={mobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen}
        searchOpen={searchOpen}
        setSearchOpen={setSearchOpen}
        searchValue={searchValue}
        setSearchValue={setSearchValue}
        onSearchSubmit={onSearchSubmit}
        currentPage={page}
      />

      <main id="conteudo-principal" className="flex-1">
        {page === 'home' && <HomePage goTo={goTo} {...sharedProductProps} />}
        {page === 'products' && (
          <ProductsPage goTo={goTo} initialCategory={activeCategory} initialSegment={activeSegment} initialSearch={activeSearch} {...sharedProductProps} />
        )}
        {page === 'product-detail' && (
          <ProductDetailPage productId={selectedProductId} goTo={goTo} {...sharedProductProps} />
        )}
        {page === 'cart' && (
          <CartPage cart={cart} goTo={goTo} updateQty={updateQty} removeFromCart={removeFromCart} cartTotal={cartTotal} />
        )}
        {page === 'checkout' && (
          <CheckoutPage cart={cart} cartTotal={cartTotal} goTo={goTo} onConfirmOrder={onConfirmOrder} />
        )}
        {page === 'success' && <SuccessPage orderNumber={orderNumber} goTo={goTo} />}
        {page === 'about' && <AboutPage goTo={goTo} />}
        {page === 'contact' && <ContactPage />}
      </main>

      <Footer goTo={goTo} />
      <Toast message={toast} />
      <WhatsAppFloatingButton />

    </div>
  );
}
